    assert_eq!(candidate(vec!["fish","dog","cat","dogfishcat"]), vec!['dogfishcat']);
    assert_eq!(candidate(vec!["a","aa","aaa","aaaa"]), vec!['aa', 'aaa', 'aaaa']);
