    assert_eq!(candidate(vec!["apple","banana","applepie","apples","pineapple","pine","pie"]), vec!['applepie', 'pineapple']);
    assert_eq!(candidate(vec!["ab","abc","abcd","abcde","abcdef"]), vec![]);
